from typing import Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class Reaction(pydantic.BaseModel):
    reaction: str
    counter: int


class ReactionAddResultsSchema(pydantic.BaseModel):
    msgId: int
    chatId: str
    reactions: list[Reaction]
    myReaction: str


class ReactionAddResponseSchema(BaseRapiResponseSchema):
    results: ReactionAddResultsSchema


class ReactionRemoveResponseSchema(BaseRapiResponseSchema): ...


class Reaction(pydantic.BaseModel):
    reaction: str
    counter: int


class ReactionInfo(pydantic.BaseModel):
    msgId: int
    chatId: str
    reactions: list[Reaction]
    myReaction: Optional[str] = None


class ReactionGetResultsSchema(pydantic.BaseModel):
    reactions: list[ReactionInfo]


class ReactionGetResponseSchema(BaseRapiResponseSchema):
    results: ReactionGetResultsSchema


class UserReaction(pydantic.BaseModel):
    user: str
    reaction: str
    time: int


class Person(pydantic.BaseModel):
    sn: str
    firstName: str
    middleName: Optional[str]
    lastName: str
    friendly: str


class ReactionListResultsSchema(pydantic.BaseModel):
    reactions: list[UserReaction]
    newest: str
    oldest: str
    exhausted: bool
    persons: list[Person]


class ReactionListResponseSchema(BaseRapiResponseSchema):
    results: ReactionListResultsSchema
